/*
  VisionX installer for Scriptable.
  Downloads the latest VisionX.js from GitHub into your Scriptable scripts.
  Run it again any time to update. Your presets, triggers and settings are kept.
  https://github.com/gadominas/VisionX

  Generated by app-blueprints/repo-site/tools/make-installer.js from repo-site/templates/install.js.
  Don't edit it here: change the template or docs/site/repo.json, then generate it again.
*/

const APP_URL = "https://raw.githubusercontent.com/gadominas/VisionX/main/VisionX.js";
const APP_NAME = "VisionX";
const APP_MARK = "const APP_ID = 'visionx'";   // the download must be this app, not an error page

async function say(title, message, openLabel) {
  const a = new Alert();
  a.title = title;
  a.message = message;
  if (openLabel) a.addAction(openLabel);
  a.addCancelAction(openLabel ? "Later" : "OK");
  return (await a.present()) === 0;
}

// Install next to this script, in iCloud or on the device, wherever your scripts live.
function scriptsFolder() {
  const here = module.filename;
  const dir = here.slice(0, here.lastIndexOf("/"));
  try {
    const icloud = FileManager.iCloud();
    if (icloud.fileExists(here)) return { fm: icloud, dir };
  } catch (_) {}
  return { fm: FileManager.local(), dir };
}

async function install() {
  const req = new Request(APP_URL);
  req.timeoutInterval = 30;
  let code;
  try {
    code = await req.loadString();
  } catch (e) {
    await say("Couldn't download " + APP_NAME, "Check your internet connection and try again.\n\n" + e.message);
    return;
  }
  const status = req.response && req.response.statusCode;
  if (status !== 200 || code.indexOf(APP_MARK) === -1) {
    await say("Couldn't download " + APP_NAME, "GitHub answered with HTTP " + status + ". Try again in a moment.");
    return;
  }

  const { fm, dir } = scriptsFolder();
  const path = fm.joinPath(dir, APP_NAME + ".js");
  const existed = fm.fileExists(path);
  if (existed) {
    if (fm.isFileStoredIniCloud(path) && !fm.isFileDownloaded(path)) await fm.downloadFileFromiCloud(path);
    if (fm.readString(path) === code) {
      if (await say(APP_NAME + " is up to date", "You already have the latest version.", "Open " + APP_NAME)) openApp();
      return;
    }
  }
  fm.writeString(path, code);
  const title = existed ? APP_NAME + " updated" : APP_NAME + " installed";
  const msg = existed
    ? "You now have the latest version. Your presets, triggers and settings are kept."
    : "It's in your script list. Apple Intelligence works straight away; for Claude or OpenAI, add a key in Settings › AI settings.";
  if (await say(title, msg, "Open " + APP_NAME)) openApp();
}

function openApp() {
  Safari.open("scriptable:///run/" + encodeURIComponent(APP_NAME));
}

await install();
